Here's how to test your `DataFetcher` with modern MSTest patterns:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _sut;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        var client = new HttpClient(_handler) { BaseAddress = new Uri("https://example.com") };
        _sut = new DataFetcher(client);
    }

    [TestMethod]
    public async Task FetchAsync_SuccessResponse_ReturnsContent()
    {
        // Arrange
        _handler.ResponseContent = "hello world";

        // Act
        var result = await _sut.FetchAsync("https://example.com/data",
            _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)] // Cooperative timeout via CancellationToken
    public async Task FetchAsync_WithTimeout_CompletesInTime()
    {
        _handler.ResponseContent = "fast response";

        var result = await _sut.FetchAsync("https://example.com/data",
            _testContext.CancellationToken);

        Assert.IsNotNull(result);
    }

    [TestMethod]
    public async Task FetchAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // Pre-cancel

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _sut.FetchAsync("https://example.com/data", cts.Token));
    }

    [TestMethod]
    public async Task FetchAsync_ServerError_ThrowsHttpRequestException()
    {
        _handler.StatusCode = System.Net.HttpStatusCode.InternalServerError;

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _sut.FetchAsync("https://example.com/data",
                _testContext.CancellationToken));
    }

    // Minimal test double for HttpMessageHandler
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        public string ResponseContent { get; set; } = string.Empty;
        public System.Net.HttpStatusCode StatusCode { get; set; } = System.Net.HttpStatusCode.OK;

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var response = new HttpResponseMessage(StatusCode)
            {
                Content = new StringContent(ResponseContent)
            };
            return Task.FromResult(response);
        }
    }
}
```

**Key patterns demonstrated:**

1. **`TestContext` via constructor injection** — gives access to `CancellationToken` for cooperative cancellation
2. **`[Timeout(5000)]` + `_testContext.CancellationToken`** — MSTest cancels the token when the timeout fires, so always flow it into your async calls
3. **`Assert.ThrowsExactlyAsync<T>`** — modern exception assertion (replaces `[ExpectedException]`)
4. **`HttpMessageHandler` test double** — avoids real HTTP calls while respecting the cancellation token
5. **Sealed test class, AAA structure, descriptive names** — standard conventions

For the project file, use `MSTest.Sdk` for the simplest setup:

```xml
<Project Sdk="MSTest.Sdk">
  <PropertyGroup>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
</Project>
```
